use crate::provenance::{CalcResult,VerificationStatus};use std::collections::BTreeMap;
pub struct FinanceResult{pub npv:CalcResult,pub irr:CalcResult,pub lcoe:CalcResult,pub payback:CalcResult}
pub fn pro_forma(capex:f64,annual_cash:f64,energy:f64,years:usize,discount:f64,tariff:f64)->FinanceResult{let npv_v=-capex+(1..=years).map(|y|annual_cash/(1.0+discount).powi(y as i32)).sum::<f64>();let mut i=BTreeMap::new();i.insert("capex".into(),capex);i.insert("discount".into(),discount);let npv=CalcResult::new("NPV",npv_v,"currency","-capex+sum(cashflow/(1+r)^t)",i,VerificationStatus::Estimated);let irr=CalcResult::new("IRR",(annual_cash/capex).max(0.0),"fraction","annual_cash/capex approximation",BTreeMap::new(),VerificationStatus::Estimated);let lcoe=CalcResult::new("LCOE",capex/(energy*years as f64),"currency/kWh","capex/discounted energy",BTreeMap::new(),VerificationStatus::Estimated);let pay=CalcResult::new("simple_payback",capex/(annual_cash.max(1e-9)*tariff.max(1e-9)),"years","capex/annual benefit",BTreeMap::new(),VerificationStatus::Estimated);FinanceResult{npv,irr,lcoe,payback:pay}}
